globalThis.__FillBARSMedicalTemplates__.skt = {"extension": "docx", "entries": [{"name": "[Content_Types].xml", "data": ""}, {"name": "_rels/.rels", "data": ""}, {"name": "word/document.xml", "data": ""}, {"name": "word/_rels/document.xml.rels", "data": ""}, {"name": "word/theme/theme1.xml", "data": ""}, {"name": "word/settings.xml", "data": ""}, {"name": "word/styles.xml", "data": ""}, {"name": "word/webSettings.xml", "data": ""}, {"name": "word/fontTable.xml", "data": ""}, {"name": "docProps/core.xml", "data": ""}, {"name": "docProps/app.xml", "data": ""}], "fields": ["department", "fullName", "birthDate", "historyNumber", "diagnosis", "icdCode", "clinicalInfo", "studyRestrictions", "anatomicArea", "studyType", "studyPurpose", "doctorPosition", "doctorName", "medicalOrganization", "organizationAddress", "doctorContacts", "documentDate"], "preview": "<p style=\"text-align:right\"><span style=\"font-size:12.0pt\">Приложение № 1</span></p><p style=\"text-align:right\"><span style=\"font-size:12.0pt\">к приказу главного врача</span></p><p style=\"text-align:right\"><span style=\"font-size:12.0pt\">от 22.11.2024г. № 629</span></p><p style=\"text-align:center\"><span style=\"font-weight:bold;font-size:12.0pt\">НАПРАВЛЕНИЕ</span></p><p style=\"text-align:center\"><span style=\"font-weight:bold;font-size:12.0pt\">на рентгенологическое исследование, СКТ исследование</span></p><p style=\"text-align:center\"><span style=\"font-weight:bold;font-size:12.0pt\">(нужное подчеркнуть)</span></p><p style=\"text-align:center\"><span style=\"font-weight:bold;font-size:12.0pt\">для </span><span style=\"font-weight:bold;font-size:12.0pt\">стационарной </span><span style=\"font-weight:bold;font-size:12.0pt\"> помощи</span></p><p style=\"\"><span style=\"font-size:12.0pt\">Указать подразделение, направляющее на </span><span style=\"font-size:12.0pt\">исследование:</span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"> {{department}}</span></p><p style=\"\"><span style=\"font-size:12.0pt\">Ф.И.О. </span><span style=\"font-size:12.0pt\">пациента:</span><span style=\"font-weight:bold;font-size:12.0pt\"></span><span style=\"font-weight:bold;font-size:12.0pt\"> {{fullName}}</span></p><p style=\"\"><span style=\"font-size:12.0pt\">Дата рождения: {{birthDate}}</span><span style=\"font-weight:bold;font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span></p><p style=\"\"><span style=\"font-size:12.0pt\">Медицинская карта пациента, получающего медицинскую помощь в </span><span style=\"font-size:12.0pt\">стационарных</span><span style=\"font-size:12.0pt\"> условиях №</span><span style=\"font-weight:bold;font-size:9.0pt\"> {{historyNumber}}</span><span style=\"font-weight:bold;font-size:9.0pt\"></span></p><p style=\"\"></p><p style=\"\"><span style=\"font-size:12.0pt\">Диагноз основного заболевания с кодом МКБ-</span><span style=\"font-size:12.0pt\">10:</span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"> {{diagnosis}} {{icdCode}}</span><span style=\"font-size:12.0pt\"></span></p><p style=\"\"><span style=\"font-size:12.0pt\">Дополнительные клинические сведения (симптомы, результаты </span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\">исследований, </span><span style=\"font-size:12.0pt\">вмешательств</span><span style=\"font-size:12.0pt\">а, последнее рентгенологическое или </span><span style=\"font-size:12.0pt\">СКТ исследование</span><span style=\"font-size:12.0pt\">)</span><span style=\"font-size:12.0pt\">:</span><span style=\"font-size:12.0pt\"> {{clinicalInfo}}</span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span></p><p style=\"\"><span style=\"font-size:12.0pt\">Ограничения к проведению рентгенологического исследования (при наличии):</span></p><p style=\"\"><span style=\"font-size:12.0pt\">{{studyRestrictions}}</span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span></p><p style=\"\"><span style=\"font-size:12.0pt\">Анатомическая область и (или) орган (органы), подлежащие обследованию:</span></p><p style=\"\"><span style=\"font-size:12.0pt\">{{anatomicArea}}</span><span style=\"font-size:12.0pt\"></span></p><p style=\"\"><span style=\"font-size:12.0pt\">Вид необходимого рентгенологического, СКТ исследования:</span></p><p style=\"\"><span style=\"font-size:12.0pt\">{{studyType}}</span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span></p><p style=\"\"><span style=\"font-size:12.0pt\">Цель назначенного рентгенологического исследования:</span></p><p style=\"\"><span style=\"font-size:12.0pt\">{{studyPurpose}}</span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span></p><p style=\"\"><span style=\"font-size:12.0pt\">Ф.И.О. и должность лечащего врача: {{doctorPosition}} {{doctorName}}</span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span></p><p style=\"\"><span style=\"font-size:12.0pt\">Наименование медицинской организации, в которую направляется пациент для </span><span style=\"font-size:12.0pt\">проведениярентгенологического</span><span style=\"font-size:12.0pt\"> исследования с указанием адреса:</span></p><p style=\"\"><span style=\"font-size:12.0pt\">{{medicalOrganization}}</span><span style=\"font-size:12.0pt\"> {{organizationAddress}}</span><span style=\"font-size:12.0pt\"></span></p><p style=\"\"><span style=\"font-size:12.0pt\">Контактный телефон, адрес электронной почты лечащего </span><span style=\"font-size:12.0pt\">врача:</span><span style=\"font-size:12.0pt\"> {{doctorContacts}}</span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span></p><p style=\"\"><span style=\"font-size:12.0pt\">Дата выдачи направления: {{documentDate}}</span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span><span style=\"font-size:12.0pt\"></span></p><p style=\"\"><span style=\"font-size:12.0pt\">Подпись врача:</span></p><p style=\"text-align:right\"></p>", "checkboxes": {}};
